1	/*
2	 * SPDX-License-Identifier: MIT
3	 * SPDX-FileCopyrightText: 2026 japes98
4	 *
5	 * The store (store.h; docs/DESIGN-NOTES.md, M7; docs/STORE-FORMAT.md):
6	 * SPI0's flash commands (HW-47), the ring of sectors and its records.
7	 */
8	
9	#include "store.h"
10	#include "WL82.h"
11	
12	/* HW-47: SPI0's CON bit 12 makes a transfer receive into BUF, bit 15
13	 * reads 1 when a byte is done, writing bit 14 clears it; the chip select
14	 * is PD0, low to select. The chip's commands. */
15	#define SPI_RX       (1u << 12)
16	#define SPI_CLEAR    (1u << 14)
17	#define SPI_DONE     (1u << 15)
18	#define CS_PIN       1u
19	#define CMD_READ     0x03u
20	#define CMD_STATUS   0x05u
21	#define CMD_WREN     0x06u
22	#define CMD_PROGRAM  0x02u
23	#define CMD_ERASE    0x20u
24	#define CMD_ID       0x9Fu
25	#define STATUS_BUSY  0x01u
26	/* How long a command may keep the chip busy before it counts as failed:
27	 * far past the longest erase (12 ms, HW-77). */
28	#define BUSY_LIMIT_TICKS (3000u * 24000u)
29	
30	/* The formats (docs/STORE-FORMAT.md). */
31	#define SECTOR_MAGIC  0x31534253u   /* "SBS1" in memory order */
32	#define FORMAT        1u
33	#define RECORD_MAGIC  0xA5u
34	#define HEADER        12u           /* a record's header */
35	#define BLOCK         16u           /* records start on a 16-byte boundary */
36	/* The largest record: a firmware kind's part (BR-9), larger than the
37	 * base's (a patch, 112 bytes). */
38	#define RECORD_MAX    ((HEADER + STORE_FW_TAG + STORE_FW_PART + 4 + BLOCK - 1) / BLOCK * BLOCK)
39	#define NONE          0xFFFFFFFFu
40	
41	/* The keys: each user slot, then the selection, the settings and the
42	 * reset record. A key's newest valid record: its sequence number and
43	 * chip offset (0: none, as no record starts at offset 0). */
44	#define KEY_SELECTION STORE_SLOTS
45	#define KEY_SETTINGS  (STORE_SLOTS + 1u)
46	#define KEY_RESET     (STORE_SLOTS + 2u)
47	#define KEYS          (STORE_SLOTS + 3u)
48	/* Since clean-1027 (BR-9) the firmware kinds' parts follow the base's
49	 * keys, STORE_FW_KEYS of them, each the newest record of one part of one
50	 * kind and id (fwk: which, its part count and its write's tag), a place
51	 * free while its addr is 0. */
52	#define ALL_KEYS      (KEYS + STORE_FW_KEYS)
53	static struct { u32 seq, addr; } key[ALL_KEYS];
54	static struct { u8 kind, id, part, parts; u32 tag; } fwk[STORE_FW_KEYS];
55	volatile struct sb_store_fw_record sb_store_fw;
56	
57	/* The sectors' sequence numbers as start-up found them, and the ring. */
58	static u32 sector_seq[STORE_SECTORS];
59	static u8 sector_valid[STORE_SECTORS];
60	static u32 head = NONE, head_seq, append, next_seq = 1;
61	
62	static u8 sector_buf[STORE_SECTOR] __attribute__((aligned(4)));
63	static u8 record_buf[RECORD_MAX], check_buf[RECORD_MAX];
64	/* A sector's header, read or about to be written (static: main's stack
65	 * is small, R-PERF-3). */
66	static u8 h[BLOCK];
67	
68	volatile struct sb_store_record sb_store __attribute__((section(".beacon.store")));
69	
70	#if defined(SB_TEST_STORE_CUT)
71	/* The power cut test build (tools/fw-suite.py): two words at this chip
72	 * offset, below the store, which only the test's flash file writes: the
73	 * commands to send whole, then the bytes of the next page program to send
74	 * before the cut (0: none). The cut is a halt with interrupts off. */
75	#define CUT_PARAM 0xE8000u
76	static u32 cut_after = NONE, cut_bytes;
77	#endif
78	
79	/* --- CRC-32 (the common one: reflected, polynomial 0xEDB88320, all ones
80	 * in and out), by nibbles. ------------------------------------------- */
81	static const u32 crc_nibble[16] = {
82	    0x00000000u, 0x1DB71064u, 0x3B6E20C8u, 0x26D930ACu, 0x76DC4190u, 0x6B6B51F4u,
83	    0x4DB26158u, 0x5005713Cu, 0xEDB88320u, 0xF00F9344u, 0xD6D6A3E8u, 0xCB61B38Cu,
84	    0x9B64C2B0u, 0x86D3D2D4u, 0xA00AE278u, 0xBDBDF21Cu,
85	};
86	
87	static u32 crc32(const u8 *p, u32 n)
88	{
89	    u32 c = 0xFFFFFFFFu;
90	
91	    while (n--) {
92	        c ^= *p++;
93	        c = c >> 4 ^ crc_nibble[c & 0xF];
94	        c = c >> 4 ^ crc_nibble[c & 0xF];
95	    }
96	    return ~c;
97	}
98	
99	static u32 rd32(const u8 *p)
100	{
101	    return (u32)p[0] | (u32)p[1] << 8 | (u32)p[2] << 16 | (u32)p[3] << 24;
102	}
103	
104	static void wr32(u8 *p, u32 v)
105	{
106	    p[0] = (u8)v;
107	    p[1] = (u8)(v >> 8);
108	    p[2] = (u8)(v >> 16);
109	    p[3] = (u8)(v >> 24);
110	}
111	
112	/* --- SPI0 and the chip's commands (HW-47) ---------------------------- */
113	static void select(void)
114	{
115	    JL_PORTD->OUT &= ~CS_PIN;
116	}
117	
118	static void deselect(void)
119	{
120	    JL_PORTD->OUT |= CS_PIN;
121	}
122	
123	/* One byte out, and its time on the bus. */
124	static void clock_byte(u32 b)
125	{
126	    JL_SPI0->BUF = b;
127	    while (!(JL_SPI0->CON & SPI_DONE))
128	        ;
129	    JL_SPI0->CON |= SPI_CLEAR;
130	}
131	
132	/* A byte in. The read of BUF is always used: fwtest 0.5.0 can run a
133	 * dual-issue pair around a read whose result is unused wrongly
134	 * (HARNESS.md, "Instructions"), so the send side never reads it. */
135	static u32 xfer(u32 b)
136	{
137	    clock_byte(b);
138	    return JL_SPI0->BUF & 0xFFu;
139	}
140	
141	static void send(u32 b)
142	{
143	    JL_SPI0->CON &= ~SPI_RX;
144	    clock_byte(b);
145	}
146	
147	static void command(u32 cmd, u32 addr)
148	{
149	    select();
150	    send(cmd);
151	    send(addr >> 16 & 0xFFu);
152	    send(addr >> 8 & 0xFFu);
153	    send(addr & 0xFFu);
154	}
155	
156	static void read(u32 addr, u8 *buf, u32 n)
157	{
158	    command(CMD_READ, addr);
159	    JL_SPI0->CON |= SPI_RX;
160	    while (n--)
161	        *buf++ = (u8)xfer(0xFFu);
162	    JL_SPI0->CON &= ~SPI_RX;
163	    deselect();
164	}
165	
166	#if defined(SB_TEST_STORE_BUSY)
167	/* The busy test build: each command keeps main as long as the part's
168	 * longest (HW-77: a 4 KiB erase 12 ms, a page program 3 ms); fwtest's
169	 * chip is never busy (HW-82). */
170	#define BUSY_ERASE_TICKS   (12u * 24000u)
171	#define BUSY_PROGRAM_TICKS (3u * 24000u)
172	static void busy_for(u32 ticks)
173	{
174	    u32 t = sb_now();
175	
176	    while (sb_now() - t < ticks)
177	        ;
178	}
179	#endif
180	
181	/* Waits while the chip says it is busy; 0 when it is done. Interrupts
182	 * stay on all the while, and everything they run is in RAM. */
183	static int wait_ready(void)
184	{
185	    u32 t = sb_now(), status, d;
186	
187	    do {
188	        select();
189	        send(CMD_STATUS);
190	        JL_SPI0->CON |= SPI_RX;
191	        status = xfer(0xFFu);
192	        JL_SPI0->CON &= ~SPI_RX;
193	        deselect();
194	        d = sb_now() - t;
195	    } while ((status & STATUS_BUSY) && d < BUSY_LIMIT_TICKS);
196	    return status & STATUS_BUSY ? -1 : 0;
197	}
198	
199	static void write_enable(void)
200	{
201	    select();
202	    send(CMD_WREN);
203	    deselect();
204	}
205	
206	static void trace(u32 kind, u32 addr)
207	{
208	    u32 n = sb_store.trace_count;
209	
210	    sb_store.trace[n % STORE_TRACE] = kind << 28 | addr;
211	    sb_store.trace_count = n + 1;
212	}
213	
214	#if defined(SB_TEST_STORE_CUT)
215	static void cut(void)
216	{
217	    __asm__ volatile("cli");
218	    for (;;)
219	        ;
220	}
221	#endif
222	
223	static int erase(u32 addr)
224	{
225	#if defined(SB_TEST_STORE_CUT)
226	    if (sb_store.commands == cut_after)
227	        cut();
228	#endif
229	    write_enable();
230	    command(CMD_ERASE, addr);
231	    deselect();
232	    sb_store.commands++;
233	    sb_store.erases++;
234	    trace(1, addr);
235	#if defined(SB_TEST_STORE_BUSY)
236	    busy_for(BUSY_ERASE_TICKS);
237	#endif
238	    return wait_ready();
239	}
240	
241	/* Programs n bytes at addr, a page program for each page they touch. */
242	static int program(u32 addr, const u8 *data, u32 n)
243	{
244	    while (n) {
245	        u32 room = STORE_PAGE - addr % STORE_PAGE, k = n < room ? n : room, i, send_n = k;
246	#if defined(SB_TEST_STORE_CUT)
247	        if (sb_store.commands == cut_after) {
248	            if (!cut_bytes)
249	                cut();
250	            send_n = cut_bytes < k ? cut_bytes : k;
251	        }
252	#endif
253	        write_enable();
254	        command(CMD_PROGRAM, addr);
255	        for (i = 0; i < send_n; i++)
256	            send(data[i]);
257	        deselect();
258	#if defined(SB_TEST_STORE_CUT)
259	        if (sb_store.commands == cut_after)
260	            cut();
261	#endif
262	        sb_store.commands++;
263	        sb_store.programs++;
264	        trace(2, addr);
265	#if defined(SB_TEST_STORE_BUSY)
266	        busy_for(BUSY_PROGRAM_TICKS);
267	#endif
268	        if (wait_ready())
269	            return -1;
270	        addr += k;
271	        data += k;
272	        n -= k;
273	    }
274	    return 0;
275	}
276	
277	/* Programs, then reads back: STORE_OK if every byte is as written. */
278	static int program_verify(u32 addr, const u8 *data, u32 n)
279	{
280	    u32 i;
281	
282	    if (program(addr, data, n))
283	        return STORE_ERR_VERIFY;
284	    read(addr, check_buf, n);
285	    for (i = 0; i < n; i++)
286	        if (check_buf[i] != data[i])
287	            return STORE_ERR_VERIFY;
288	    return STORE_OK;
289	}
290	
291	/* --- Records ---------------------------------------------------------- */
292	static u32 sector_addr(u32 s)
293	{
294	    return STORE_BASE + s * STORE_SECTOR;
295	}
296	
297	static u32 next_sector(u32 s)
298	{
299	    return s == NONE ? 0 : (s + 1) % STORE_SECTORS;
300	}
301	
302	static int key_of(u32 kind, u32 id)
303	{
304	    if (kind == STORE_PATCH)
305	        return id < STORE_SLOTS ? (int)id : -1;
306	    if (id)
307	        return -1;
308	    return kind == STORE_SELECTION ? (int)KEY_SELECTION : kind == STORE_SETTINGS ? (int)KEY_SETTINGS
309	         : kind == STORE_RESET ? (int)KEY_RESET : -1;
310	}
311	
312	static u32 record_size(u32 len)
313	{
314	    return (HEADER + len + 4 + BLOCK - 1) / BLOCK * BLOCK;
315	}
316	
317	static int fw_kind(u32 kind)
318	{
319	    return kind >= STORE_FW_KIND_FIRST && kind <= STORE_FW_KIND_LAST;
320	}
321	
322	/* A record at p, with at most room bytes after it: its payload's length,
323	 * or -1 if it is not one (a bad magic or length, or its CRC fails). */
324	static int record_check(const u8 *p, u32 room)
325	{
326	    u32 len = (u32)p[4] | (u32)p[5] << 8;
327	    u32 max = fw_kind(p[1]) ? STORE_FW_TAG + STORE_FW_PART : STORE_MAX_PAYLOAD;
328	
329	    if (p[0] != RECORD_MAGIC || len > max || record_size(len) > room)
330	        return -1;
331	    return crc32(p, HEADER + len) == rd32(p + HEADER + len) ? (int)len : -2;
332	}
333	
334	/* Bytes from a record at addr to the end of its sector: the most a
335	 * read of it may take. */
336	static u32 room_at(u32 addr)
337	{
338	    u32 r = STORE_SECTOR - (addr - STORE_BASE) % STORE_SECTOR;
339	
340	    return r < RECORD_MAX ? r : RECORD_MAX;
341	}
342	
343	static void count_live(void)
344	{
345	    u32 k, n = 0, f = 0;
346	
347	    for (k = 0; k < ALL_KEYS; k++)
348	        n += key[k].addr != 0;
349	    for (k = KEYS; k < ALL_KEYS; k++)
350	        f += key[k].addr != 0;
351	    sb_store.live = n;
352	    sb_store_fw.parts_live = f;
353	}
354	
355	/* The key of a firmware kind's part: its place, or a free one if alloc
356	 * (filled in), or -1. */
357	static int fw_key(u32 kind, u32 id, u32 part, int alloc)
358	{
359	    u32 i;
360	
361	    for (i = 0; i < STORE_FW_KEYS; i++)
362	        if (key[KEYS + i].addr && fwk[i].kind == kind && fwk[i].id == id && fwk[i].part == part)
363	            return (int)(KEYS + i);
364	    if (!alloc)
365	        return -1;
366	    for (i = 0; i < STORE_FW_KEYS; i++)
367	        if (!key[KEYS + i].addr) {
368	            fwk[i].kind = (u8)kind;
369	            fwk[i].id = (u8)id;
370	            fwk[i].part = (u8)part;
371	            return (int)(KEYS + i);
372	        }
373	    return -1;
374	}
375	
376	static int blank(const u8 *p, u32 n)
377	{
378	    while (n--)
379	        if (*p++ != 0xFFu)
380	            return 0;
381	    return 1;
382	}
383	
384	/* Reads one valid sector whole and takes its records into the keys. For
385	 * the head, also where its erased tail begins. */
386	static void scan(u32 s)
387	{
388	    u32 off = BLOCK, end = BLOCK;
389	
390	    read(sector_addr(s), sector_buf, STORE_SECTOR);
391	    while (off + BLOCK <= STORE_SECTOR) {
392	        const u8 *p = sector_buf + off;
393	        int len, k;
394	        u32 seq;
395	
396	        if (blank(p, BLOCK)) {
397	            off += BLOCK;
398	            continue;
399	        }
400	        len = record_check(p, STORE_SECTOR - off);
401	        if (len < 0) {
402	            if (len == -2)
403	                sb_store.crc_bad++;
404	            else
405	                sb_store.skipped++;
406	            off += BLOCK;
407	            end = off;
408	            continue;
409	        }
410	        seq = rd32(p + 8);
411	        if (seq >= next_seq)
412	            next_seq = seq + 1;
413	        if (fw_kind(p[1]))
414	            /* A firmware kind's part (BR-9): its index below its count,
415	             * its tag in its payload's first word. */
416	            k = p[6] < p[7] && p[7] <= STORE_FW_PARTS && (u32)len >= STORE_FW_TAG
417	                ? fw_key(p[1], p[2], p[6], 1) : -1;
418	        else
419	            k = key_of(p[1], p[2]);
420	        if (k < 0)
421	            sb_store.unknown++;
422	        else if (seq > key[k].seq || !key[k].addr) {
423	            key[k].seq = seq;
424	            key[k].addr = sector_addr(s) + off;
425	            if (k >= (int)KEYS) {
426	                fwk[k - KEYS].parts = p[7];
427	                fwk[k - KEYS].tag = rd32(p + HEADER);
428	            }
429	        }
430	        off += record_size((u32)len);
431	        end = off;
432	    }
433	    if (s == head)
434	        append = end;
435	}
436	
437	void store_init(void)
438	{
439	    u32 t = sb_now(), s, k, best = 0;
440	
441	    deselect();
442	    select();
443	    send(CMD_ID);
444	    JL_SPI0->CON |= SPI_RX;
445	    sb_store.part = xfer(0xFFu) << 16;
446	    sb_store.part |= xfer(0xFFu) << 8;
447	    sb_store.part |= xfer(0xFFu);
448	    JL_SPI0->CON &= ~SPI_RX;
449	    deselect();
450	#if defined(SB_TEST_STORE_CUT)
451	    read(CUT_PARAM, h, 8);
452	    cut_after = rd32(h);
453	    cut_bytes = rd32(h + 4);
454	#endif
455	    for (s = 0; s < STORE_SECTORS; s++) {
456	        read(sector_addr(s), h, BLOCK);
457	        sector_valid[s] = rd32(h) == SECTOR_MAGIC && h[8] == FORMAT && crc32(h, 12) == rd32(h + 12);
458	        sector_seq[s] = sector_valid[s] ? rd32(h + 4) : 0;
459	        if (sector_valid[s]) {
460	            sb_store.valid_sectors++;
461	            if (head == NONE || sector_seq[s] > best) {
462	                best = sector_seq[s];
463	                head = s;
464	            }
465	        }
466	    }
467	    head_seq = best;
468	    for (s = 0; s < STORE_SECTORS; s++)
469	        if (sector_valid[s])
470	            scan(s);
471	    /* A reset voids every record older than it, the firmware kinds' too. */
472	    if (key[KEY_RESET].addr)
473	        for (k = 0; k < ALL_KEYS; k++)
474	            if (k != KEY_RESET && key[k].addr && key[k].seq < key[KEY_RESET].seq) {
475	                key[k].addr = 0;
476	                sb_store.voided++;
477	            }
478	    /* A firmware kind's part not of its payload's newest write (another
479	     * tag than part 0's, another count, or past it) is not live. */
480	    for (k = KEYS; k < ALL_KEYS; k++) {
481	        const int h = key[k].addr && fwk[k - KEYS].part
482	            ? fw_key(fwk[k - KEYS].kind, fwk[k - KEYS].id, 0, 0) : -1;
483	        if (key[k].addr && fwk[k - KEYS].part
484	            && (h < 0 || fwk[h - KEYS].tag != fwk[k - KEYS].tag || fwk[h - KEYS].parts != fwk[k - KEYS].parts
485	                || fwk[k - KEYS].part >= fwk[k - KEYS].parts)) {
486	            key[k].addr = 0;
487	            sb_store_fw.stale++;
488	        }
489	    }
490	    count_live();
491	    sb_store.head = head;
492	    sb_store.head_seq = head_seq;
493	    sb_store.append = head == NONE ? 0 : append;
494	    sb_store.next_seq = next_seq;
495	    sb_store.init_ticks = sb_now() - t;
496	    sb_store.marker = STORE_MARKER;
497	}
498	
499	/* A firmware kind's payload (BR-9): every part of its newest write, in
500	 * order, or -1. */
501	static int get_fw(u32 kind, u32 id, u8 *buf, u32 max, u32 *version)
502	{
503	    int h = fw_key(kind, id, 0, 0), k, len;
504	    u32 part, i, n = 0;
505	
506	    if (h < 0)
507	        return -1;
508	    for (part = 0; part < fwk[h - KEYS].parts; part++) {
509	        k = fw_key(kind, id, part, 0);
510	        if (k < 0 || fwk[k - KEYS].tag != fwk[h - KEYS].tag || fwk[k - KEYS].parts != fwk[h - KEYS].parts)
511	            return -1;
512	        read(key[k].addr, check_buf, room_at(key[k].addr));
513	        len = record_check(check_buf, room_at(key[k].addr));
514	        if (len < (int)STORE_FW_TAG || rd32(check_buf + HEADER) != fwk[h - KEYS].tag
515	            || n + (u32)len - STORE_FW_TAG > max)
516	            return -1;
517	        for (i = STORE_FW_TAG; i < (u32)len; i++)
518	            buf[n++] = check_buf[HEADER + i];
519	        if (!part)
520	            *version = check_buf[3];
521	    }
522	    return (int)n;
523	}
524	
525	int store_get(u32 kind, u32 id, u8 *buf, u32 max, u32 *version)
526	{
527	    int k = key_of(kind, id), len;
528	    u32 i;
529	
530	    if (fw_kind(kind))
531	        return id <= 255 ? get_fw(kind, id, buf, max, version) : -1;
532	    if (k < 0 || !key[k].addr)
533	        return -1;
534	    read(key[k].addr, check_buf, room_at(key[k].addr));
535	    len = record_check(check_buf, room_at(key[k].addr));
536	    if (len < 0 || (u32)len > max)
537	        return -1;
538	    for (i = 0; i < (u32)len; i++)
539	        buf[i] = check_buf[HEADER + i];
540	    *version = check_buf[3];
541	    return len;
542	}
543	
544	/* Erases sector n and makes it the head, one past the head before it. */
545	static int open_sector(u32 n)
546	{
547	    int r;
548	
549	    if (erase(sector_addr(n)))
550	        return STORE_ERR_VERIFY;
551	    wr32(h, SECTOR_MAGIC);
552	    wr32(h + 4, head_seq + 1);
553	    h[8] = FORMAT;
554	    h[9] = h[10] = h[11] = 0;
555	    wr32(h + 12, crc32(h, 12));
556	    r = program_verify(sector_addr(n), h, BLOCK);
557	    if (r)
558	        return r;
559	    head = n;
560	    head_seq++;
561	    append = BLOCK;
562	    sb_store.head = head;
563	    sb_store.head_seq = head_seq;
564	    return STORE_OK;
565	}
566	
567	/* Keys whose newest record is in sector s. */
568	static u32 live_in(u32 s)
569	{
570	    u32 k, n = 0, a = sector_addr(s);
571	
572	    for (k = 0; k < ALL_KEYS; k++)
573	        n += key[k].addr >= a && key[k].addr < a + STORE_SECTOR;
574	    return n;
575	}
576	
577	/* Appends the record in record_buf (its sequence number filled in here)
578	 * to the head, which has room: STORE_OK once it reads back. The bytes are
579	 * spent whatever happens. */
580	static int append_record(int k, u32 len)
581	{
582	    u32 n = HEADER + len + 4, addr = sector_addr(head) + append;
583	    int r;
584	
585	    wr32(record_buf + 8, next_seq);
586	    wr32(record_buf + HEADER + len, crc32(record_buf, HEADER + len));
587	    r = program_verify(addr, record_buf, n);
588	    append += record_size(len);
589	    sb_store.append = append;
590	    next_seq++;
591	    sb_store.next_seq = next_seq;
592	    if (r) {
593	        sb_store.verify_fail++;
594	        return r;
595	    }
596	    key[k].seq = next_seq - 1;
597	    key[k].addr = addr;
598	    sb_store.records++;
599	    return STORE_OK;
600	}
601	
602	/* Copies every live record of the sector after the head into the head,
603	 * so the ring can erase it when it comes round. */
604	static int compact(void)
605	{
606	    u32 m = next_sector(head), a = sector_addr(m), k;
607	    int len, r;
608	
609	    for (k = 0; k < ALL_KEYS; k++) {
610	        if (key[k].addr < a || key[k].addr >= a + STORE_SECTOR)
611	            continue;
612	        read(key[k].addr, record_buf, room_at(key[k].addr));
613	        len = record_check(record_buf, room_at(key[k].addr));
614	        if (len < 0) {
615	            /* It read well at start-up; never copy it wrong. */
616	            key[k].addr = 0;
617	            continue;
618	        }
619	        if (append + record_size((u32)len) > STORE_SECTOR)
620	            return STORE_ERR_FULL;
621	        r = append_record((int)k, (u32)len);
622	        if (r)
623	            return r;
624	        sb_store.copies++;
625	    }
626	    return STORE_OK;
627	}
628	
629	/* Room in the head for a record of size bytes, the ring kept so the
630	 * sector after the head holds nothing live. */
631	static int make_room(u32 size)
632	{
633	    int r;
634	
635	    if (head == NONE && (r = open_sector(0)) != STORE_OK)
636	        return r;
637	    if ((r = compact()) != STORE_OK)
638	        return r;
639	    if (append + size > STORE_SECTOR) {
640	        u32 n = next_sector(head);
641	        if (live_in(n))
642	            return STORE_ERR_FULL;
643	        if ((r = open_sector(n)) != STORE_OK)
644	            return r;
645	        if ((r = compact()) != STORE_OK)
646	            return r;
647	        if (append + size > STORE_SECTOR)
648	            return STORE_ERR_FULL;
649	    }
650	    return STORE_OK;
651	}
652	
653	/* One record from payload (len bytes) after an optional tag: room made,
654	 * written, read back; twice if it read back wrong. */
655	static int put_record(int k, u32 kind, u32 id, u32 version, u32 part, u32 parts, const u32 *tag,
656	                      const u8 *payload, u32 len)
657	{
658	    int r = STORE_ERR_VERIFY, tries;
659	    u32 i, n = len + (tag ? STORE_FW_TAG : 0), at = HEADER;
660	
661	    for (tries = 0; tries < 2 && r == STORE_ERR_VERIFY; tries++) {
662	        if ((r = make_room(record_size(n))) != STORE_OK)
663	            break;
664	        record_buf[0] = RECORD_MAGIC;
665	        record_buf[1] = (u8)kind;
666	        record_buf[2] = (u8)id;
667	        record_buf[3] = (u8)version;
668	        record_buf[4] = (u8)n;
669	        record_buf[5] = (u8)(n >> 8);
670	        record_buf[6] = (u8)part;
671	        record_buf[7] = (u8)parts;
672	        at = HEADER;
673	        if (tag) {
674	            wr32(record_buf + at, *tag);
675	            at += STORE_FW_TAG;
676	        }
677	        for (i = 0; i < len; i++)
678	            record_buf[at + i] = payload[i];
679	        r = append_record(k, n);
680	    }
681	    return r;
682	}
683	
684	/* A firmware kind's payload (BR-9): its parts in order, each tagged with
685	 * the next sequence number as the first is begun; then the parts past
686	 * the new count are no longer live. A write that stops part way leaves
687	 * the old payload until its first part is whole, then none (never a mix
688	 * of two writes) until it is written again. */
689	static int put_fw(u32 kind, u32 id, u32 version, const u8 *payload, u32 len)
690	{
691	    u32 parts = len ? (len + STORE_FW_PART - 1) / STORE_FW_PART : 1, part, free = 0, i, tag = next_seq;
692	    int k, r;
693	
694	    /* Places for every part first, so a write never stops for want of one. */
695	    for (i = 0; i < STORE_FW_KEYS; i++)
696	        free += !key[KEYS + i].addr;
697	    for (part = 0; part < parts; part++)
698	        free += fw_key(kind, id, part, 0) >= 0;
699	    if (free < parts)
700	        return STORE_ERR_FULL;
701	    for (part = 0; part < parts; part++) {
702	        u32 n = len - part * STORE_FW_PART < STORE_FW_PART ? len - part * STORE_FW_PART : STORE_FW_PART;
703	
704	        if (!part)
705	            tag = next_seq;
706	        k = fw_key(kind, id, part, 1);
707	        r = put_record(k, kind, id, version, part, parts, &tag, payload + part * STORE_FW_PART, n);
708	        if (r != STORE_OK)
709	            return r;
710	        fwk[k - KEYS].parts = (u8)parts;
711	        fwk[k - KEYS].tag = tag;
712	        sb_store_fw.parts_written++;
713	    }
714	    for (part = parts; part < STORE_FW_PARTS; part++)
715	        if ((k = fw_key(kind, id, part, 0)) >= 0)
716	            key[k].addr = 0;
717	    sb_store_fw.payloads++;
718	    return STORE_OK;
719	}
720	
721	static int put(u32 kind, u32 id, u32 version, const u8 *payload, u32 len)
722	{
723	    int k = key_of(kind, id);
724	
725	    if (version > 255 || (fw_kind(kind) ? id > 255 || len > STORE_FW_MAX : k < 0 || len > STORE_MAX_PAYLOAD))
726	        return STORE_ERR_ARG;
727	    /* Only a part whose rules and times are known is written (HW-76). */
728	    if (sb_store.part != STORE_PART)
729	        return STORE_ERR_PART;
730	    if (fw_kind(kind))
731	        return put_fw(kind, id, version, payload, len);
732	    return put_record(k, kind, id, version, 0, 0, 0, payload, len);
733	}
734	
735	int store_put(u32 kind, u32 id, u32 version, const u8 *payload, u32 len)
736	{
737	    u32 t = sb_now(), d;
738	    int r = put(kind, id, version, payload, len);
739	
740	    d = sb_now() - t;
741	    if (d > sb_store.put_max)
742	        sb_store.put_max = d;
743	    if (r != STORE_OK)
744	        sb_store.refused++;
745	    sb_store.last_result = r;
746	    count_live();
747	    return r;
748	}
749	
750	int store_reset(void)
751	{
752	    int r = store_put(STORE_RESET, 0, 0, 0, 0);
753	    u32 k;
754	
755	    if (r == STORE_OK)
756	        for (k = 0; k < ALL_KEYS; k++)
757	            if (k != KEY_RESET)
758	                key[k].addr = 0;
759	    count_live();
760	    return r;
761	}
762	
763	#if defined(SB_TEST_STORE_WIPE)
764	/* The wipe test build (tools/fw-suite.py): once main runs, erases the
765	 * image's own sectors, from chip offset 0x4000 to the image's end, so
766	 * that anything still read through the code window reads erased flash
767	 * (docs/DESIGN-NOTES.md, M7). */
768	extern u32 __data_load[], __data_start[], __data_end[];
769	
770	void sb_test_store_wipe(void)
771	{
772	    u32 end = 0x4000u + ((u32)__data_load - 0x02000000u) + ((u32)__data_end - (u32)__data_start), a;
773	
774	    for (a = 0x4000u; a < end; a += STORE_SECTOR)
775	        erase(a);
776	}
777	#endif
778

