    s = st.Store(sectors=sectors)
    for i in range(st.SLOTS): s.put(st.PATCH, i, 2, pattern(20 + i, 112))
    s.put(st.SELECTION, 0, 1, bytes([5, 0, 0, 0])); s.put(st.SETTINGS, 0, 4, bytes(42))
    return s
w = full_store(st.WIDE_SECTORS); w.put_fw(0x80,7,1,pattern(2,4096)); w.put_fw(0x81,0,1,pattern(9,10))
