print("large", len(w.commands), sum(c[0]=="erase" for c in w.commands))
for name, step in (("small",0x86),("patch",0x87)):
    s = full_store(st.SECTORS); s.put_fw(0x81,0,1,pattern(9,10)); s.put_fw(0x80,7,1,pattern(1,1500))
