cat > $CLAUDE_JOB_DIR/tmp/treecmp.py <<'EOF'
import sys, os, json, collections
a, b = sys.argv[1], sys.argv[2]
fa = {os.path.relpath(os.path.join(r, f), a) for r, _, fs in os.walk(a) for f in fs}
fb = {os.path.relpath(os.path.join(r, f), b) for r, _, fs in os.walk(b) for f in fs}
print("files:", len(fa), len(fb), "only in a:", len(fa - fb), "only in b:", len(fb - fa))
for x in sorted(fa ^ fb)[:10]: print("  one side only:", x)
kinds = collections.Counter(); other = []
def flat(o, p=""):
    if isinstance(o, dict):
        for k, v in o.items(): yield from flat(v, p + "/" + k)
    elif isinstance(o, list):
        for i, v in enumerate(o): yield from flat(v, p + "[%d]" % i)
    else: yield p, o
keys = collections.Counter()
for f in sorted(fa & fb):
    da, db = open(os.path.join(a, f), "rb").read(), open(os.path.join(b, f), "rb").read()
    if da == db: continue
    base = os.path.basename(f)
    if base.endswith(".json"):
        try:
            ja, jb = dict(flat(json.loads(da))), dict(flat(json.loads(db)))
            d = sorted(k for k in set(ja) | set(jb) if ja.get(k) != jb.get(k))
            for k in d: keys[k] += 1
            kinds["json:" + base] += 1
            continue
        except Exception: pass
    if base == "runner.txt": kinds["runner.txt"] += 1; continue
    other.append(f)
print("differing:", sum(kinds.values()) + len(other), dict(kinds))
print("json keys that differ:", dict(keys))
print("other differing files:", len(other))
for x in other[:20]: print("  ", x)
EOF
echo ok

