import sys, struct; sys.path.insert(0,'tools')
import store as st
def pattern(p, n): return bytes((i * (2 * p + 1) + p) & 0xFF for i in range(n))
def old_copies(before_chip, after_chip, old_tag, start_seq):
    return sum(1 for (sec, off, seq, kind, ident, ver, pl) in st.Image(after_chip).records
               if kind == 0x80 and ident == 7 and pl[:4] == old_tag and seq >= start_seq)
for setup in range(6):
    s = st.Store(); s.put_fw(0x81,0,1,pattern(9,10))
    for r in range(setup+1): s.put_fw(0x80,7,1,pattern(1,3000))
    s.put_fw(0x8F,0,1,bytes([0x84]))
    old_tag = struct.pack("<I", s._commit(0x80,7)[3]); start = s.next_seq; before = s.chip()
    s.commands=[]; s.put_fw(0x80,7,1,pattern(4,3000))
    print(setup, len(s.commands), "erases", sum(c[0]=="erase" for c in s.commands), "old-part copies", old_copies(before, s.chip(), old_tag, start))
EOF
python3 $CLAUDE_JOB_DIR/tmp/pre3.py

